keyframes:
@keyframes disco { 
  0% { transform: translateY(-50%) rotate(0deg); }
  100% { transform: translateY(-50%) rotate(360deg); }
}

@keyframes open-slide-down-fade { 
  0% { opacity: 0; transform: translateY(-4px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes close-slide-up-fade { 
  0% { opacity: 1; transform: translateY(0px); }
  100% { opacity: 0; transform: translateY(-4px); }
}

@keyframes open-slide-up-fade { 
  0% { opacity: 0; transform: translateY(4px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes close-slide-down-fade { 
  0% { opacity: 1; transform: translateY(0px); }
  100% { opacity: 0; transform: translateY(4px); }
}

@keyframes open-scale-in-fade { 
  0% { opacity: 0; animation-composition: add, accumulate; transform: scale(0.98); }
  100% { opacity: 1; animation-composition: add, accumulate; transform: scale(1); }
}

@keyframes open-scale-up-fade { 
  0% { opacity: 0; transform: scale(0.98) translateY(5px); }
  100% { opacity: 1; transform: scale(1) translateY(0px); }
}

@keyframes hero-text-slide-up-fade { 
  0% { opacity: 0; transform: translateY(16px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes webgl-scale-in-fade { 
  0% { opacity: 0; transform: scale(0.7); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes header-slide-down-fade { 
  0% { opacity: 0; transform: translateY(-16px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes caret-blink { 
  0% { opacity: 1; }
  20% { opacity: 0; }
  50% { opacity: 0; }
  70% { opacity: 1; }
  100% { opacity: 1; }
}

@keyframes scroll-shadow-line-y { 
  0% { box-shadow: 0 -1px 0 0 transparent, 0 1px 0 0 var(--scroll-shadow-line-color); }
  0.01%, 99.99% { box-shadow: 0 -1px 0 0 var(--scroll-shadow-line-color), 0 1px 0 0 var(--scroll-shadow-line-color); }
  100% { box-shadow: 0 -1px 0 0 var(--scroll-shadow-line-color), 0 1px 0 0 transparent; }
}

@keyframes scroll-fade-x { 
  0% { mask-image: linear-gradient(90deg, rgb(0, 0, 0) calc(100% - 24px), rgba(0, 0, 0, 0)); }
  0.01%, 99.99% { mask-image: linear-gradient(90deg, rgba(0, 0, 0, 0), rgb(0, 0, 0) 24px, rgb(0, 0, 0) calc(100% - 24px), rgba(0, 0, 0, 0)); }
  100% { mask-image: linear-gradient(90deg, rgba(0, 0, 0, 0), rgb(0, 0, 0) 24px); }
}

@keyframes hero-scale-in { 
  0% { opacity: 0; transform: scale(0.97); }
  30% { opacity: 0; }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes dots-float-01 { 
  0% { opacity: 0; transform: translate(0px); }
  20% { opacity: 1; transform: translate(-24%, -36%); }
  50% { opacity: 0; transform: translate(-60%); }
  80% { opacity: 1; transform: translate(-24%, 12%); }
  100% { opacity: 1; transform: translate(0px); }
}

@keyframes dots-float-02 { 
  0% { opacity: 0; transform: translate(0px); }
  20% { opacity: 1; transform: translate(24%, -36%); }
  50% { opacity: 0; transform: translate(60%); }
  80% { opacity: 1; transform: translate(12%, 36%); }
  100% { opacity: 1; transform: translate(0px); }
}

@keyframes bars-bounce { 
  10% { transform: scaleX(0.84) translate(1px); }
  30% { transform: scaleX(1.5) translate(2px); }
  60% { transform: scaleX(0.84) translate(2px); }
  80% { transform: scaleX(0.96) translate(1px); }
  100% { transform: scaleX(1) translate(2px); }
}

@keyframes forge-live-ping { 
  0% { opacity: 0.5; transform: scale(1); }
  60%, 100% { opacity: 0; transform: scale(3.5); }
}

@keyframes forge-enter-flicker { 
  0% { opacity: 0; }
  20% { opacity: 1; }
  35% { opacity: 0.2; }
  50% { opacity: 1; }
  60% { opacity: 0.5; }
  70%, 100% { opacity: 1; }
}
